const $=id=>document.getElementById(id);const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const avg=(h,ab)=>ab>0?(h/ab).toFixed(3):'—';const koreanDate=()=>new Intl.DateTimeFormat('en-CA',{timeZone:'Asia/Seoul',year:'numeric',month:'2-digit',day:'2-digit'}).format(new Date());let players=[],snapshot=null,selected='';const slots=[{position:'중견수',abbr:'CF',cls:'pos-cf'},{position:'좌익수',abbr:'LF',cls:'pos-lf'},{position:'우익수',abbr:'RF',cls:'pos-rf'},{position:'유격수',abbr:'SS',cls:'pos-ss'},{position:'2루수',abbr:'2B',cls:'pos-2b'},{position:'3루수',abbr:'3B',cls:'pos-3b'},{position:'1루수',abbr:'1B',cls:'pos-1b'},{position:'포수',abbr:'C',cls:'pos-c'}];const teamColors={'LG':'#c30452','한화':'#f37321','롯데':'#041e42','KIA':'#ea0029','삼성':'#074ca1','두산':'#131230','KT':'#000000','SSG':'#ce0e2d','NC':'#315288','키움':'#6b183c'};$('date').value=koreanDate();function teams(){const prev=$('team').value;$('team').innerHTML='<option value="">전체 팀</option>'+[...new Set(players.map(p=>p.team))].sort().map(t=>`<option>${esc(t)}</option>`).join('');if(players.some(p=>p.team===prev))$('team').value=prev}function reason(r){const p=r.player,s=p.at_bats?p.hits/p.at_bats:0,re=p.recent10.at_bats?p.recent10.hits/p.recent10.at_bats:0,op=r.split?.at_bats?r.split.hits/r.split.at_bats:0;if(r.split?.at_bats&&op>=s)return `상대팀전 ${op.toFixed(3)} · ${r.split.at_bats}타수`;if(p.recent10.at_bats&&re>s)return `최근 ${re.toFixed(3)} · 시즌 대비 +${(re-s).toFixed(3)}`;return `시즌 타율 ${s.toFixed(3)}`}function portrait(p){const fallback=`https://6ptotvmi5753.edge.naverncp.com/KBO_IMAGE/person/middle/2025/${encodeURIComponent(p.player_id)}.jpg`;const src=p.profile_image||p.image_url||fallback;return `<span class="portrait-shell" style="--team:${teamColors[p.team]||'#1d6b4f'}"><img class="field-avatar" src="${esc(src)}" alt="${esc(p.name)}" loading="lazy" onerror="if(this.dataset.fallback){this.hidden=true;this.nextElementSibling.hidden=false}else{this.dataset.fallback='1';this.src='${fallback}' }"><span class="avatar-fallback" hidden>${esc(p.name.slice(-1))}</span></span>`}function buildLineup(ranked){const used=new Set();const picks=slots.map(slot=>{const row=ranked.find(r=>!used.has(r.key)&&r.player.position===slot.position);if(row)used.add(row.key);return {...slot,row}});const dh=ranked.find(r=>!used.has(r.key));if(dh)used.add(dh.key);picks.push({position:'지명타자',abbr:'DH',cls:'pos-dh',row:dh});return picks}function renderField(ranked){const lineup=buildLineup(ranked);$('fieldCards').innerHTML=lineup.map(({position,abbr,cls,row})=>{if(!row)return `<div class="field-card empty-slot ${cls}"><span class="pos">${abbr}<small>${position}</small></span><span class="empty-position">추천 없음</span></div>`;const r=row,p=r.player;return `<button class="field-card ${cls} ${r.key===selected?'active':''}" data-key="${esc(r.key)}" style="--team:${teamColors[p.team]||'#1d6b4f'}"><span class="pos">${abbr}<small>${position}</small></span>${portrait(p)}<span class="field-player"><b>${esc(p.name)}</b><small>${esc(p.team)} vs ${esc(r.opponent)}</small></span><span class="field-score">${r.score.toFixed(1)}<small>점</small></span><span class="field-reason">${esc(reason(r))}</span></button>`}).join('')}function renderDetail(r){if(!r){$('detail').innerHTML='<h2>분석할 선수가 없습니다</h2><p>날짜나 팀을 바꿔보세요.</p>';return}const p=r.player;$('detail').innerHTML=`<div class="eyelabel">PLAYER INSIGHT</div><h2>${esc(p.name)}</h2><div class="meta">${esc(p.team)} · ${esc(p.position||'포지션 확인 중')} · vs ${esc(r.opponent||'—')}</div><div class="result">${r.score.toFixed(1)}<small>점</small></div><p>종합점수 · 안타 확률이 아닌 비교 지표</p><div class="stat"><span>기본타율</span><b>${avg(p.hits,p.at_bats)}</b></div><div class="stat"><span>최근타율</span><b>${avg(p.recent10.hits,p.recent10.at_bats)}</b></div><div class="stat"><span>상대팀 타율</span><b>${avg(r.split?.hits,r.split?.at_bats)}</b></div><div class="explain">${esc(reason(r))}<br>기본타율 50% + 최근 30% + 상대팀 20%</div>`}function render(){if(!snapshot)return;const all=HitModel.rowsFor(players,snapshot.schedule,$('date').value);const filtered=all.filter(r=>(!$('team').value||r.player.team===$('team').value));const ranked=filtered.filter(r=>r.eligible);if(!ranked.some(r=>r.key===selected))selected=ranked[0]?.key||'';$('count').textContent=`${ranked.length}명 추천`;const games=snapshot.schedule?.games?.filter(g=>g.date===$('date').value&&!['completed','cancelled'].includes(g.status))||[];$('scheduleNote').textContent=games.length?`${$('date').value} · ${games.map(g=>`${g.away} vs ${g.home}`).join(' / ')}`:`${$('date').value} · 추천 대상 경기가 없습니다.`;renderField(ranked);let rank=0;$('rows').innerHTML=filtered.map(r=>{const p=r.player,n=r.eligible?String(++rank).padStart(2,'0'):'—';return `<tr><td><button data-key="${esc(r.key)}"><span class="num">${n}</span><b>${esc(p.name)}</b><small>${esc(p.team)}</small></button></td><td>${esc(p.position||'—')}</td><td>${avg(p.hits,p.at_bats)}</td><td>${avg(p.recent10.hits,p.recent10.at_bats)}</td><td>${r.eligible?avg(r.split?.hits,r.split?.at_bats):'—'}</td><td>${r.eligible?r.score.toFixed(1)+'점':'—'}</td></tr>`}).join('');renderDetail(ranked.find(r=>r.key===selected));document.querySelectorAll('[data-key]').forEach(b=>b.onclick=()=>{selected=b.dataset.key;render()})}$('team').onchange=render;$('date').onchange=render;async function load(){try{const res=await fetch('../kbo-data.json',{cache:'no-store'});if(!res.ok)throw Error('기록을 불러올 수 없습니다.');snapshot=await res.json();players=snapshot.players||[];$('date').min=koreanDate();$('date').max=snapshot.schedule?.end_date||koreanDate();teams();const positioned=players.filter(p=>p.position).length;$('mode').textContent='KBO 실제 기록';$('notice').textContent=`${snapshot.season} 정규시즌 · ${players.length}명 · 정확한 수비 포지션 ${positioned}명 반영`;render()}catch(e){$('mode').textContent='기록 로딩 실패';$('notice').textContent=e.message}}load();